import Foundation
import NIO
import NIOWebSocket
import Crypto

// Payment WebSocket Server - handles real-time payment confirmations
actor PaymentSessionManager {
    private var sessions: [String: PaymentSession] = [:]
    private var originWhitelist: Set<String> = ["https://payments.example.com", "https://app.example.com"]

    struct PaymentSession {
        let userId: String
        let sessionToken: String
        let channel: Channel
        var pendingAmount: Decimal
        var confirmed: Bool
    }

    func validateOrigin(_ origin: String?) -> Bool {
        guard let origin = origin else { return false }
        return originWhitelist.contains(origin)
    }

    func registerSession(userId: String, token: String, channel: Channel) {
        let session = PaymentSession(userId: userId, sessionToken: token, channel: channel, pendingAmount: 0, confirmed: false)
        sessions[token] = session
    }

    func getSession(token: String) -> PaymentSession? {
        return sessions[token]
    }

    func updatePendingAmount(token: String, amount: Decimal) {
        sessions[token]?.pendingAmount = amount
    }

    func confirmPayment(token: String) -> Bool {
        guard sessions[token] != nil else { return false }
        sessions[token]?.confirmed = true
        return true
    }
}

final class PaymentWebSocketHandler: ChannelInboundHandler {
    typealias InboundIn = WebSocketFrame
    typealias OutboundOut = WebSocketFrame

    // Reasonable upper bound for a single payment amount.
    private static let maxPaymentAmount: Decimal = 1_000_000

    private let sessionManager: PaymentSessionManager
    private let authenticatedToken: String

    init(sessionManager: PaymentSessionManager, authenticatedToken: String) {
        self.sessionManager = sessionManager
        self.authenticatedToken = authenticatedToken
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let frame = unwrapInboundIn(data)

        switch frame.opcode {
        case .text:
            handleTextFrame(context: context, frame: frame)
        case .connectionClose:
            handleClose(context: context)
        default:
            break
        }
    }

    private func handleTextFrame(context: ChannelHandlerContext, frame: WebSocketFrame) {
        var data = frame.data
        guard let text = data.readString(length: data.readableBytes) else { return }

        Task {
            await processPaymentMessage(text: text, context: context)
        }
    }

    private func processPaymentMessage(text: String, context: ChannelHandlerContext) async {
        guard let jsonData = text.data(using: .utf8),
              let message = try? JSONSerialization.jsonObject(with: jsonData) as? [String: Any],
              let action = message["action"] as? String else {
            return
        }

        switch action {
        case "initiate_payment":
            await handleInitiatePayment(message: message, context: context)
        case "confirm_payment":
            await handleConfirmPayment(message: message, context: context)
        case "get_status":
            await handleGetStatus(message: message, context: context)
        default:
            break
        }
    }

    private func handleInitiatePayment(message: [String: Any], context: ChannelHandlerContext) async {
        guard let amountStr = message["amount"] as? String,
              let amount = Decimal(string: amountStr) else {
            return
        }

        // Validate the amount is strictly positive and within an acceptable range.
        guard amount > 0, amount <= PaymentWebSocketHandler.maxPaymentAmount else {
            sendResponse(context: context, payload: ["status": "rejected", "reason": "invalid_amount"])
            return
        }

        await sessionManager.updatePendingAmount(token: authenticatedToken, amount: amount)
        sendResponse(context: context, payload: ["status": "pending", "amount": amountStr])
    }

    private func handleConfirmPayment(message: [String: Any], context: ChannelHandlerContext) async {
        let success = await sessionManager.confirmPayment(token: authenticatedToken)
        sendResponse(context: context, payload: ["status": success ? "confirmed" : "failed"])
    }

    private func handleGetStatus(message: [String: Any], context: ChannelHandlerContext) async {
        guard let session = await sessionManager.getSession(token: authenticatedToken) else {
            return
        }

        sendResponse(context: context, payload: [
            "user_id": session.userId,
            "amount": "\(session.pendingAmount)",
            "confirmed": session.confirmed ? "true" : "false"
        ])
    }

    private func sendResponse(context: ChannelHandlerContext, payload: [String: String]) {
        guard let data = try? JSONSerialization.data(withJSONObject: payload),
              let text = String(data: data, encoding: .utf8) else { return }

        var buffer = context.channel.allocator.buffer(capacity: text.utf8.count)
        buffer.writeString(text)
        let frame = WebSocketFrame(fin: true, opcode: .text, data: buffer)
        context.writeAndFlush(wrapOutboundOut(frame), promise: nil)
    }

    private func handleClose(context: ChannelHandlerContext) {
        context.close(promise: nil)
    }
}

// WebSocket upgrade handler - validates the upgrade request
final class WebSocketUpgradeHandler: ChannelInboundHandler, RemovableChannelHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    private let sessionManager: PaymentSessionManager

    init(sessionManager: PaymentSessionManager) {
        self.sessionManager = sessionManager
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let reqPart = unwrapInboundIn(data)

        guard case .head(let head) = reqPart else {
            context.fireChannelRead(data)
            return
        }

        // Extract and validate session from query parameters
        guard let components = URLComponents(string: head.uri),
              let tokenParam = components.queryItems?.first(where: { $0.name == "token" }),
              let token = tokenParam.value else {
            sendUpgradeRejection(context: context, status: .unauthorized)
            return
        }

        // Origin validation during upgrade
        let origin = head.headers.first(name: "Origin")

        Task {
            let originValid = await sessionManager.validateOrigin(origin)
            if originValid {
                await self.proceedWithUpgrade(context: context, token: token)
            } else {
                self.sendUpgradeRejection(context: context, status: .forbidden)
            }
        }
    }

    private func proceedWithUpgrade(context: ChannelHandlerContext, token: String) async {
        guard await sessionManager.getSession(token: token) != nil else {
            sendUpgradeRejection(context: context, status: .unauthorized)
            return
        }
        // Upgrade proceeds - session is valid, bind token to handler
        let handler = PaymentWebSocketHandler(sessionManager: sessionManager, authenticatedToken: token)
        try? await context.pipeline.addHandler(handler).get()
    }

    private func sendUpgradeRejection(context: ChannelHandlerContext, status: HTTPResponseStatus) {
        let headers = HTTPHeaders([("Content-Length", "0")])
        let head = HTTPResponseHead(version: .http1_1, status: status, headers: headers)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
        context.close(promise: nil)
    }
}
